sys_variable_value.value:
(function execute(inputs, outputs) {

    var currentRecord = inputs.current;

    var companyCode = inputs.codigoEmpresa;
    var contractNumber = inputs.numeroContrato;
    var numeroBP = inputs.codigoBP;
    var validade = inputs.validadeDesde;
    var validadeFormatada = formatDateToDDMMYYYY(validade);

    var myObj = {
    "CompanyCode": companyCode,
    "ContractNumber": contractNumber,
    "BusinessPartners": [
      {
        "BPNumber": numeroBP,  //mudar esse 
        "BPRoleCode": "TR0200",
        //"BPValidTo": "2024-12-31"
        "BPValidFrom": validadeFormatada
      }
    ]
  };

  function formatDateToDDMMYYYY(dateString) {
    var parts = dateString.split('/');
    var day = parts[0];
    var month = parts[1];
    var year = parts[2];

    return year + '-' + month + '-' + day;
}

   gs.info('***Integra+ '+ JSON.stringify(myObj));
    outputs.payloadbasic = myObj;

})(inputs, outputs);

